class HostContractsTest {
    @Test
    void reservationCompletionIsIdempotentAndReplayIsContiguous() {
        var store = new MemoryHostStore();
        store.create("session-1", new ModelRef("faux", "faux-1"), ".");
        store.startRun("session-1", "result-1",
                new io.github.diodeme.ji.ai.Message("message-1", io.github.diodeme.ji.ai.Message.Role.USER,
                        List.of(new io.github.diodeme.ji.ai.Content.Text("hello")), Instant.EPOCH), 0);
        var reservation = store.reserve("session-1", "command-1", "hash", "result-1", 1);
        var retryReservation = store.reserve("session-1", "command-1", "hash", "result-1", 1);
        assertEquals(reservation, retryReservation);
        SessionSnapshot terminal = store.finishRun(
                "session-1", "result-1", List.of(), Usage.ZERO, "completed", 1);
        HostStore.Commit first = store.command("session-1", "command-1", "hash")
                .flatMap(HostStore.CommandRecord::commit).orElseThrow();
        assertEquals(first, store.command("session-1", "command-1", "hash")
                .flatMap(HostStore.CommandRecord::commit).orElseThrow());
        assertEquals(terminal, store.load("session-1").orElseThrow());
        assertEquals(1, store.replay("session-1", 0).size());
        assertArrayEquals(store.replay("session-1", 0).getFirst().payload(), store.snapshot("session-1").payload());
        JiException conflict = assertThrows(JiException.class,
                () -> store.reserve("session-1", "command-1", "different", "result-1", 2));
        assertEquals(ErrorCode.COMMAND_PAYLOAD_CONFLICT, conflict.error().code());
    }

    @Test
    void rejectedExecutorAbandonsReservationAndSameCommandCanRetry() {
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Text("done"),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        var hostStore = new MemoryHostStore();
        var permissions = new PermissionBroker(Clock.systemUTC());
        var executor = new RejectOnceExecutor();
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider(permissions).executor(executor).build();
             var sessions = new SessionApplicationService(runtime)) {
            String sessionId = sessions.create(new ModelRef("faux", "faux-1"), ".").id();
            var prompts = new PromptApplicationService(sessions, hostStore);
            assertThrows(RejectedExecutionException.class, () -> prompts.prompt(sessionId, "command-1", "hello"));
            String hash = PromptApplicationService.sha256("hello".getBytes(StandardCharsets.UTF_8));
            HostStore.CommandRecord released = hostStore.command(sessionId, "command-1", hash).orElseThrow();
            assertEquals("RETRYABLE", released.status().name());
            assertFalse(sessions.hasActiveRun(sessionId));
            var retry = prompts.prompt(sessionId, "command-1", "hello");
            assertEquals(released.resultRef(), retry.runId());
            assertEquals(released.acceptedSeq(), retry.commit().acceptedSeq());
            retry.run().orElseThrow().completion().toCompletableFuture().join();
            HostStore.Commit committed = prompts.completed(retry.runId()).orElseThrow();
            assertEquals(retry.commit().acceptedSeq(), committed.acceptedSeq());
            assertEquals(retry.runId(), committed.resultRef());
            assertEquals(1, provider.capturedRequests().size());
        }
    }

    @Test
    void retryWhileReservedReturnsOriginalAcceptanceWithoutSecondPrompt() throws Exception {
        var gate = new ScriptedModelProvider.Gate();
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Wait(gate),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        var hostStore = new MemoryHostStore();
        var permissions = new PermissionBroker(Clock.systemUTC());
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider(permissions).build();
             var sessions = new SessionApplicationService(runtime)) {
            String sessionId = sessions.create(new ModelRef("faux", "faux-1"), ".").id();
            var prompts = new PromptApplicationService(sessions, hostStore);
            var first = prompts.prompt(sessionId, "command-1", "hello");
            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
            while (provider.capturedRequests().isEmpty() && System.nanoTime() < deadline) Thread.onSpinWait();
            assertEquals(1, provider.capturedRequests().size());

            var retry = prompts.prompt(sessionId, "command-1", "hello");
            assertEquals(first.runId(), retry.runId());
            assertEquals(first.commit(), retry.commit());
            assertTrue(retry.run().isEmpty());
            HostStore.CommandRecord reserved = hostStore.command(sessionId, "command-1",
                    PromptApplicationService.sha256("hello".getBytes(StandardCharsets.UTF_8))).orElseThrow();
            assertEquals(1, reserved.acceptedSeq());
            assertEquals(0, hostStore.snapshot(sessionId).revision());
            assertEquals(0, hostStore.snapshot(sessionId).baseEventSeq());
            JiException conflict = assertThrows(JiException.class,
                    () -> prompts.prompt(sessionId, "command-1", "different"));
            assertEquals(ErrorCode.COMMAND_PAYLOAD_CONFLICT, conflict.error().code());
            assertEquals("command-1", conflict.error().parameters().get("commandId"));
            assertTrue(conflict.error().parameters().containsKey("existingPayloadSha256"));
            assertTrue(conflict.error().parameters().containsKey("suppliedPayloadSha256"));

            first.run().orElseThrow().abort();
            gate.open();
            first.run().orElseThrow().completion().toCompletableFuture().join();
        }
    }

    @Test
    void embeddedStoreRollbackRestoresExactPreRunSnapshot() {
        var provider = new ScriptedModelProvider()
                .enqueue(List.of(new ScriptedModelProvider.Step.Tool("call-1", "echo", Map.of("value", "x")),
                        new ScriptedModelProvider.Step.Complete(new Usage(2, 1, 0, 0, 0),
                                ModelStreamEvent.StopReason.TOOL_USE)))
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("done"),
                        new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        var hostStore = new FailOnceFinishHostStore();
        var permissions = new PermissionBroker(Clock.systemUTC());
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .tool(io.github.diodeme.ji.agent.ToolDefinition.sync("echo", "echo", Map.of("type", "object"),
                        (arguments, cancellation) -> io.github.diodeme.ji.agent.ToolDefinition.ToolResult.text("result"))
                        .alwaysAllow())
                .permissionDecider(permissions).build();
             var sessions = new SessionApplicationService(runtime)) {
            String sessionId = sessions.create(new ModelRef("faux", "faux-1"), ".").id();
            var prompts = new PromptApplicationService(sessions, hostStore);
            var first = prompts.prompt(sessionId, "command-1", "hello");
            assertThrows(java.util.concurrent.CompletionException.class,
                    () -> first.run().orElseThrow().completion().toCompletableFuture().join());
            assertTrue(sessions.transcript(sessionId).isEmpty());
            assertEquals(Usage.ZERO, sessions.snapshot(sessionId).usage());
        }
    }

    @Test
    void terminalStoreFailureRollsBackRunAndReservationForSameIdentityRetry() {
        var provider = new ScriptedModelProvider()
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("first"),
                        new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)))
                .enqueue(List.of(new ScriptedModelProvider.Step.Text("second"),
                        new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        var hostStore = new FailOnceFinishHostStore();
        var permissions = new PermissionBroker(Clock.systemUTC());
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider(permissions).build();
             var sessions = new SessionApplicationService(runtime)) {
            String sessionId = sessions.create(new ModelRef("faux", "faux-1"), ".").id();
            var prompts = new PromptApplicationService(sessions, hostStore);
            var first = prompts.prompt(sessionId, "command-1", "hello");
            assertThrows(java.util.concurrent.CompletionException.class,
                    () -> first.run().orElseThrow().completion().toCompletableFuture().join());
            assertThrows(java.util.concurrent.CompletionException.class,
                    () -> prompts.completed(first.runId()));
            String hash = PromptApplicationService.sha256("hello".getBytes(StandardCharsets.UTF_8));
            HostStore.CommandRecord released = hostStore.command(sessionId, "command-1", hash).orElseThrow();
            assertEquals("RETRYABLE", released.status().name());
            assertEquals(1, hostStore.finishAttempts());
            assertFalse(sessions.hasActiveRun(sessionId));
            assertTrue(sessions.snapshot(sessionId).activeRun().isEmpty());
            assertEquals(2, sessions.snapshot(sessionId).revision());
            assertEquals(0, hostStore.snapshot(sessionId).revision());
            assertEquals(0, hostStore.snapshot(sessionId).baseEventSeq());

            var retry = prompts.prompt(sessionId, "command-1", "hello");
            assertEquals(first.runId(), retry.runId());
            assertEquals(released.acceptedSeq(), retry.commit().acceptedSeq());
            retry.run().orElseThrow().completion().toCompletableFuture().join();
            HostStore.Commit committed = prompts.completed(retry.runId()).orElseThrow();
            assertEquals(1, committed.acceptedSeq());
            assertEquals(1, committed.eventSeq());
            assertEquals(1, committed.snapshotRevision());
            assertEquals(2, provider.capturedRequests().size());
        }
    }

    @Test
    void hostServiceRejectsSplitSessionAndHostStores() {
        var permissions = new PermissionBroker(Clock.systemUTC());
        var hostStore = new MemoryHostStore();
        try (var runtime = new AgentRuntimeBuilder().provider(new ScriptedModelProvider())
                .sessionStore(new io.github.diodeme.ji.session.memory.MemorySessionStore())
                .permissionDecider(permissions).build();
             var sessions = new SessionApplicationService(runtime)) {
            assertThrows(IllegalArgumentException.class,
                    () -> new PromptApplicationService(sessions, hostStore));
        }
    }

    @Test
    void terminalCompletionAtomicallyPersistsCanonicalSnapshotAndDurableEvent() {
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Text("done"),
                new ScriptedModelProvider.Step.Complete(new Usage(2, 1, 0, 0, 0),
                        ModelStreamEvent.StopReason.STOP)));
        var hostStore = new MemoryHostStore();
        var permissions = new PermissionBroker(Clock.systemUTC());
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider(permissions).build();
             var sessions = new SessionApplicationService(runtime)) {
            String sessionId = sessions.create(new ModelRef("faux", "faux-1"), ".").id();
            var prompts = new PromptApplicationService(sessions, hostStore);
            var first = prompts.prompt(sessionId, "command-1", "hello");
            first.run().orElseThrow().completion().toCompletableFuture().join();
            HostStore.Commit commit = prompts.completed(first.runId()).orElseThrow();
            assertEquals(sessions.snapshot(sessionId), hostStore.load(sessionId).orElseThrow());
            assertEquals(1, commit.eventSeq());
            assertEquals(1, commit.snapshotRevision());
            String snapshot = new String(hostStore.snapshot(sessionId).payload(), StandardCharsets.UTF_8);
            assertTrue(snapshot.contains("\"text\":\"hello\""));
            assertTrue(snapshot.contains("\"text\":\"done\""));
            assertTrue(snapshot.contains("\"outcome\":\"completed\""));
            assertTrue(snapshot.contains("\"inputTokens\":2"));
            var retry = prompts.prompt(sessionId, "command-1", "hello");
            assertEquals(first.runId(), retry.runId());
            assertTrue(retry.run().isEmpty());
            assertEquals(1, provider.capturedRequests().size());
        }
    }

    @Test
    void activeRunIsRejectedBeforeASecondCommandIsReserved() {
        var gate = new ScriptedModelProvider.Gate();
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Wait(gate),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        var hostStore = new MemoryHostStore();
        var permissions = new PermissionBroker(Clock.systemUTC());
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider(permissions).build();
             var sessions = new SessionApplicationService(runtime)) {
            String sessionId = sessions.create(new ModelRef("faux", "faux-1"), ".").id();
            var prompts = new PromptApplicationService(sessions, hostStore);
            var first = prompts.prompt(sessionId, "command-1", "one");
            assertThrows(IllegalStateException.class, () -> prompts.prompt(sessionId, "command-2", "two"));
            assertTrue(hostStore.command(sessionId, "command-2",
                    PromptApplicationService.sha256("two".getBytes(StandardCharsets.UTF_8))).isEmpty());
            first.run().orElseThrow().abort();
            gate.open();
            first.run().orElseThrow().completion().toCompletableFuture().join();
        }
    }

    @Test
    void hcpSchemaCarriesHandshakeAckAndReplayContracts() {
        var hello = ClientHello.newBuilder().setMinProtocolVersion(1).setMaxProtocolVersion(1)
                .setClientId("client-1").addRequiredCapabilities("session.replay").build();
        assertEquals(1, hello.getMinProtocolVersion());
        assertEquals("session.replay", hello.getRequiredCapabilities(0));
    }

    @Test
    void hcpApplicationConsumesHandshakeCommandsAndReplayFrames() {
        var provider = new ScriptedModelProvider().enqueue(List.of(
                new ScriptedModelProvider.Step.Text("done"),
                new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        var hostStore = new MemoryHostStore();
        var permissions = new PermissionBroker(Clock.systemUTC());
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(hostStore)
                .permissionDecider(permissions).build();
             var sessions = new SessionApplicationService(runtime)) {
            String sessionId = sessions.create(new ModelRef("faux", "faux-1"), ".").id();
            var prompts = new PromptApplicationService(sessions, hostStore);
            var gateway = new HcpSessionGateway(prompts, "host-1");
            var welcome = gateway.handle(Envelope.newBuilder().setConnectionId("connection-1")
                    .setClientHello(ClientHello.newBuilder().setMinProtocolVersion(1).setMaxProtocolVersion(1)
                            .setClientId("client-1").addRequiredCapabilities("session.replay")).build());
            assertTrue(welcome.getFirst().hasServerWelcome());
            assertEquals("host-1", welcome.getFirst().getServerWelcome().getHostId());

            var command = Envelope.newBuilder().setConnectionId("connection-1")
                    .setCommand(Command.newBuilder().setSessionId(sessionId).setCommandId("command-hcp")
                            .setExpectedRevision(0).setPayload(ByteString.copyFromUtf8("hello"))).build();
            var ack = gateway.handle(command).getFirst();
            assertTrue(ack.hasCommandAck());
            assertEquals(1, ack.getCommandAck().getAcceptedSeq());
            prompts.completed(ack.getCommandAck().getResultRef()).orElseThrow();
            var replay = gateway.handle(Envelope.newBuilder().setConnectionId("connection-1")
                    .setReplayRequest(ReplayRequest.newBuilder().setSessionId(sessionId)
                            .setLastAckSeq(0).setSnapshotRevision(0)).build());
            assertTrue(replay.getFirst().hasSnapshotChunk());
            assertEquals(1, replay.getFirst().getSnapshotChunk().getSnapshotRevision());

            var retry = gateway.handle(command).getFirst();
            assertTrue(retry.hasCommandAck());
            assertEquals(ack.getCommandAck().getResultRef(), retry.getCommandAck().getResultRef());
            assertEquals(1, provider.capturedRequests().size());

            var stale = gateway.handle(command.toBuilder().setCommand(command.getCommand().toBuilder()
                    .setCommandId("command-stale").setExpectedRevision(0)).build()).getFirst();
            assertTrue(stale.hasError());
            assertEquals("queue.revision_conflict", stale.getError().getCode());
            assertTrue(hostStore.command(sessionId, "command-stale",
                    PromptApplicationService.sha256("hello".getBytes(StandardCharsets.UTF_8))).isEmpty());

            var conflict = gateway.handle(command.toBuilder().setCommand(command.getCommand().toBuilder()
                    .setPayload(ByteString.copyFromUtf8("different"))).build()).getFirst();
            assertTrue(conflict.hasError());
            assertEquals("command.payload_conflict", conflict.getError().getCode());
            assertEquals("command-hcp", conflict.getError().getParametersMap().get("commandId"));
            assertTrue(conflict.getError().getParametersMap().containsKey("existingPayloadSha256"));
            assertTrue(conflict.getError().getParametersMap().containsKey("suppliedPayloadSha256"));
        }
    }

    @Test
    void hcpRejectsUnsupportedCapabilityAndPayload() {
        var permissions = new PermissionBroker(Clock.systemUTC());
        var hostStore = new MemoryHostStore();
        try (var runtime = new AgentRuntimeBuilder().provider(new ScriptedModelProvider())
                .sessionStore(hostStore).permissionDecider(permissions).build();
             var sessions = new SessionApplicationService(runtime)) {
            var gateway = new HcpSessionGateway(
                    new PromptApplicationService(sessions, hostStore), "host-1");
            var response = gateway.handle(Envelope.newBuilder().setConnectionId("connection-1")
                    .setClientHello(ClientHello.newBuilder().setMinProtocolVersion(1).setMaxProtocolVersion(1)
                            .addRequiredCapabilities("unknown.required")).build()).getFirst();
            assertTrue(response.hasError());
            assertEquals("protocol.invalid_message", response.getError().getCode());
            assertTrue(gateway.handle(Envelope.newBuilder().setConnectionId("connection-1").build())
                    .getFirst().hasError());
        }
    }

    @Test
    void loopbackTokenIsSingleUse() {
        var service = new LocalTokenService(new SecureRandom(), Clock.fixed(Instant.EPOCH, ZoneOffset.UTC));
        String token = [REDACTED_CREDENTIAL]
        assertFalse(service.exchange(token, false).isPresent());
        assertTrue(service.exchange(token, true).isPresent());
        assertFalse(service.exchange(token, true).isPresent());
    }

    private static final class RejectOnceExecutor extends AbstractExecutorService {
        private final java.util.concurrent.ExecutorService delegate = java.util.concurrent.Executors.newSingleThreadExecutor();
        private final AtomicBoolean rejected = new AtomicBoolean();

        @Override public void execute(Runnable command) {
            if (rejected.compareAndSet(false, true)) throw new RejectedExecutionException("injected rejection");
            delegate.execute(command);
        }
        @Override public void shutdown() { delegate.shutdown(); }
        @Override public List<Runnable> shutdownNow() { return delegate.shutdownNow(); }
        @Override public boolean isShutdown() { return delegate.isShutdown(); }
        @Override public boolean isTerminated() { return delegate.isTerminated(); }
        @Override public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
            return delegate.awaitTermination(timeout, unit);
        }
    }

    private static final class FailOnceFinishHostStore implements HostStore {
        private final MemoryHostStore delegate = new MemoryHostStore();
        private final AtomicBoolean fail = new AtomicBoolean(true);
        private int finishAttempts;

        int finishAttempts() { return finishAttempts; }
        @Override public SessionSnapshot create(String sessionId, ModelRef model, String workingDirectory) {
            return delegate.create(sessionId, model, workingDirectory);
        }
        @Override public Optional<SessionSnapshot> load(String sessionId) { return delegate.load(sessionId); }
        @Override public SessionSnapshot startRun(String sessionId, String runId,
                io.github.diodeme.ji.ai.Message userMessage, long expectedRevision) {
            return delegate.startRun(sessionId, runId, userMessage, expectedRevision);
        }
        @Override public SessionSnapshot append(String sessionId, String runId,
                List<io.github.diodeme.ji.ai.Message> messages, Usage usage,
                Optional<SessionSnapshot.ActiveRun> activeRun, long expectedRevision) {
            return delegate.append(sessionId, runId, messages, usage, activeRun, expectedRevision);
        }
        @Override public SessionSnapshot rollbackRun(
                String sessionId, String runId, SessionSnapshot beforeRun, long expectedRevision) {
            return delegate.rollbackRun(sessionId, runId, beforeRun, expectedRevision);
        }
        @Override public SessionSnapshot finishRun(String sessionId, String runId,
                List<io.github.diodeme.ji.ai.Message> messages, Usage usage, String outcome, long expectedRevision) {
            finishAttempts++;
            if (fail.compareAndSet(true, false)) throw new IllegalStateException("injected terminal CAS failure");
            return delegate.finishRun(sessionId, runId, messages, usage, outcome, expectedRevision);
        }
        @Override public Reservation reserve(String sessionId, String commandId, String payloadHash,
                String resultRef, long expectedSessionRevision) {
            return delegate.reserve(sessionId, commandId, payloadHash, resultRef, expectedSessionRevision);
        }
        @Override public void release(String sessionId, String commandId, String payloadHash, String resultRef) {
            delegate.release(sessionId, commandId, payloadHash, resultRef);
        }
        @Override public Optional<CommandRecord> command(String sessionId, String commandId, String payloadHash) {
            return delegate.command(sessionId, commandId, payloadHash);
        }
        @Override public Snapshot snapshot(String sessionId) { return delegate.snapshot(sessionId); }
        @Override public List<DurableEvent> replay(String sessionId, long afterEventSeq) {
            return delegate.replay(sessionId, afterEventSeq);
        }
    }
}

