class HostContractsTest {
    @Test
    void reservationCompletionIsIdempotentAndReplayIsContiguous() {
        var store = new MemoryHostStore();
        store.create("session-1", new ModelRef("faux", "faux-1"), ".", Instant.EPOCH);
        var reservation = store.acceptPrompt(
                "session-1", "command-1", "hash", "result-1", 0,
                "local", List.of("hello"), List.of());
        var prompt = new io.github.diodeme.ji.ai.Message(
                "message-1", io.github.diodeme.ji.ai.Message.Role.USER,
                List.of(new io.github.diodeme.ji.ai.Content.Text("hello")), Instant.EPOCH);
        SessionDocument running = store.update("session-1", 0, document -> document.startRun(
                new SessionDocument.RunStart("result-1", "turn-1", "attempt-1", "result-entry-1",
                        prompt, "operation-start-1", "attempt-record-1", Instant.EPOCH)));
        var retryReservation = store.acceptPrompt(
                "session-1", "command-1", "hash", "replacement", 1,
                "local", List.of("ignored"), List.of());
        assertEquals(reservation.acceptedSeq(), retryReservation.acceptedSeq());
        assertEquals(reservation.resultRef(), retryReservation.resultRef());
        assertEquals(reservation.status(), retryReservation.status());
        SessionDocument terminal = store.update("session-1", 1, document -> document.finishRun(
                new SessionDocument.RunCompletion("result-1", 0, "turn-1", 0,
                        "attempt-1", 0, List.of(), Usage.ZERO,
                        io.github.diodeme.ji.session.model.CanonicalSessionState.RunOutcome.COMPLETED,
                        "usage-record-1", "operation-finish-1", Instant.EPOCH)));
        HostStore.Commit first = store.command("session-1", "command-1", "hash")
                .flatMap(HostStore.CommandRecord::commit).orElseThrow();
        assertEquals(first, store.command("session-1", "command-1", "hash")
                .flatMap(HostStore.CommandRecord::commit).orElseThrow());
        assertEquals(terminal, store.load("session-1").orElseThrow());
        assertEquals(2, store.replay("session-1", 0).size());
        assertArrayEquals(store.replay("session-1", 0).getLast().payload(), store.snapshot("session-1").payload());
        JiException conflict = assertThrows(JiException.class,
                () -> store.acceptPrompt("session-1", "command-1", "different", "result-1", 2,
                        "local", List.of("hello"), List.of()));
        assertEquals(ErrorCode.COMMAND_PAYLOAD_CONFLICT, conflict.error().code());
