    private static final class RejectOnceExecutor extends AbstractExecutorService {
        private final java.util.concurrent.ExecutorService delegate = java.util.concurrent.Executors.newSingleThreadExecutor();
        private final AtomicBoolean rejected = new AtomicBoolean();

        @Override public void execute(Runnable command) {
            if (rejected.compareAndSet(false, true)) throw new RejectedExecutionException("injected rejection");
            delegate.execute(command);
        }
        @Override public void shutdown() { delegate.shutdown(); }
        @Override public List<Runnable> shutdownNow() { return delegate.shutdownNow(); }
        @Override public boolean isShutdown() { return delegate.isShutdown(); }
        @Override public boolean isTerminated() { return delegate.isTerminated(); }
        @Override public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
            return delegate.awaitTermination(timeout, unit);
        }
    }

    private static final class FailOnceFinishHostStore implements HostStore {
        private final MemoryHostStore delegate = new MemoryHostStore();
        private final AtomicBoolean fail = new AtomicBoolean(true);
        private int finishAttempts;

        int finishAttempts() { return finishAttempts; }
        @Override public SessionDocument create(
                String sessionId, ModelRef model, String workingDirectory, Instant createdAt) {
            return delegate.create(sessionId, model, workingDirectory, createdAt);
        }
        @Override public Optional<SessionDocument> load(String sessionId) { return delegate.load(sessionId); }
        @Override public List<SessionDocument.Metadata> list() { return delegate.list(); }
        @Override public SessionDocument update(
                String sessionId, long expectedRevision, UnaryOperator<SessionDocument> transition) {
            SessionDocument before = delegate.load(sessionId).orElseThrow();
            SessionDocument after = transition.apply(before);
            boolean terminal = after.execution().completedRuns().size()
                    > before.execution().completedRuns().size();
            if (terminal) {
                finishAttempts++;
                if (fail.compareAndSet(true, false)) throw new IllegalStateException("injected terminal CAS failure");
            }
            return delegate.update(sessionId, expectedRevision, ignored -> after);
        }
        @Override public SessionDocument fork(
                String sourceSessionId, String newSessionId, String lane, Optional<String> targetEntryId,
                SessionDocument.ForkPosition position, Instant createdAt, long expectedSourceRevision) {
            return delegate.fork(sourceSessionId, newSessionId, lane, targetEntryId, position,
                    createdAt, expectedSourceRevision);
        }
        @Override public void delete(String sessionId, long expectedRevision) {
            delegate.delete(sessionId, expectedRevision);
        }
        @Override public PromptAcceptance acceptPrompt(
                String sessionId, String commandId, String payloadHash, String resultRef,
                long expectedSessionRevision, String clientId, List<String> content, List<String> attachments) {
            return delegate.acceptPrompt(sessionId, commandId, payloadHash, resultRef,
                    expectedSessionRevision, clientId, content, attachments);
        }
        @Override public Optional<ClaimedPrompt> claimNextPrompt(String sessionId) {
            return delegate.claimNextPrompt(sessionId);
        }
        @Override public void rollbackClaim(String sessionId, ClaimedPrompt claim) {
            delegate.rollbackClaim(sessionId, claim);
        }
        @Override public void release(String sessionId, String commandId, String payloadHash, String resultRef) {
            delegate.release(sessionId, commandId, payloadHash, resultRef);
        }
        @Override public Optional<CommandRecord> command(String sessionId, String commandId, String payloadHash) {
            return delegate.command(sessionId, commandId, payloadHash);
        }
        @Override public FollowUpQueue queue(String sessionId) { return delegate.queue(sessionId); }
        @Override public FollowUpQueue reorderQueue(
                String sessionId, List<String> itemIds, long expectedQueueRevision) {
            return delegate.reorderQueue(sessionId, itemIds, expectedQueueRevision);
        }
        @Override public FollowUpQueue promote(
                String sessionId, String itemId, long expectedQueueRevision) {
            return delegate.promote(sessionId, itemId, expectedQueueRevision);
        }
        @Override public FollowUpQueue.Removed remove(
                String sessionId, String itemId, String requestingClientId, long expectedQueueRevision) {
            return delegate.remove(sessionId, itemId, requestingClientId, expectedQueueRevision);
        }
        @Override public FollowUpQueue resumeQueue(String sessionId, long expectedQueueRevision) {
            return delegate.resumeQueue(sessionId, expectedQueueRevision);
        }
        @Override public SessionDocument beginNextTurn(
                String sessionId, long expectedSessionRevision,
                SessionInputCoordinator.OptionalInputTransition transition) {
            return delegate.beginNextTurn(sessionId, expectedSessionRevision, transition);
